tool_input.command:
node << 'EOF'
import { scriptedModel } from './test/helpers/mock-model.js';
import { getOrderStatus, answerOrderQuestion } from './src/order-agent.js';

// Test 1: Tool defined correctly and has the right properties
console.log('Tool name:', getOrderStatus.name);
console.log('Tool description:', getOrderStatus.description);
console.log('Tool parameters:', getOrderStatus.parameters);

// Test 2: answerOrderQuestion with mock model
const model = scriptedModel([
  { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }], usage: [100, 20] },
  { text: 'Order A100 is shipped and will arrive on 2026-10-09.', usage: [150, 30] },
]);

try {
  const result = await answerOrderQuestion(model, 'What is the status of my order A100?', { customerId: 'C1' });
  console.log('\nResult:', result);
  console.log('answer:', result.answer);
  console.log('lookedUp:', result.lookedUp);
  console.log('inputTokens:', result.inputTokens);
  console.log('outputTokens:', result.outputTokens);
} catch (err) {
  console.error('Error:', err.message);
  console.error(err.stack);
}
EOF
